 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for c in range(w):
        # A bottom-row 5 marks a column to turn into a vertical stack. Each
        # marker's color fills the gap above it up to the previous marker;
        # the topmost marker extends to the top and 5 fills the bottom gap.
        if grid[h-1][c] != 5:
            continue
        anchors = [(r, grid[r][c]) for r in range(h) if grid[r][c] != 0]
        for i, (r, color) in enumerate(anchors):
            upper = anchors[i-1][0] + 1 if i > 0 else 0
            for rr in range(upper, r + 1):
                out[rr][c] = color
    return out

